ITEMS.append({
 "id": "l265-news-diavaseis-3d", "title": "Διαβάσεις πεζών που μοιάζουν να «αιωρούνται»: ένα πείραμα για να κόψουν ταχύτητα οι οδηγοί", "title_en": "Pedestrian crossings that seem to 'float': an experiment to make drivers slow down", "type": "news", "level": "B2",
 "context_el": "Ακούτε μια είδηση στο μεσημεριανό δελτίο ενός τοπικού ραδιοφωνικού σταθμού στην Πάτρα.",
 "script": [
  L("Εκφωνήτρια", "f", "Τέσσερις διαβάσεις πεζών κοντά σε σχολεία της Πάτρας βάφτηκαν αυτή την εβδομάδα με έναν ασυνήθιστο τρόπο: οι λευκές λωρίδες έχουν σκιές σε γκρι και μαύρο, έτσι ώστε, από την απόσταση ενός αυτοκινήτου, να μοιάζουν με τρισδιάστατα εμπόδια που αιωρούνται πάνω από τον δρόμο.", "Four pedestrian crossings near schools in Patras were painted this week in an unusual way: the white stripes have shadows in grey and black, so that, from a car's distance, they look like three-dimensional obstacles floating above the road."),
  L("Εκφωνήτρια", "f", "Ο στόχος είναι οι οδηγοί να κόβουν ταχύτητα ενστικτωδώς, πριν καν καταλάβουν ότι πρόκειται για οφθαλμαπάτη. Παρόμοιες διαβάσεις έχουν δοκιμαστεί σε πόλεις του εξωτερικού, με αποτελέσματα που, όπως παραδέχεται ο δήμος, δεν είναι πάντα σαφή.", "The aim is for drivers to slow down instinctively, before they even realise it is an optical illusion. Similar crossings have been tried in cities abroad, with results that, as the municipality admits, are not always clear."),
  L("Εκφωνήτρια", "f", "Γι’ αυτό, το πείραμα θα διαρκέσει έξι μήνες, και κάμερες χωρίς αναγνώριση πινακίδων θα μετρούν την ταχύτητα των αυτοκινήτων πριν και μετά τη βαφή. Αν η ταχύτητα δεν μειωθεί αισθητά, οι διαβάσεις θα ξαναβαφτούν με τον συνηθισμένο τρόπο.", "That is why the experiment will last six months, and cameras without number-plate recognition will measure the speed of cars before and after the painting. If speed does not fall noticeably, the crossings will be repainted in the usual way."),
  L("Εκφωνήτρια", "f", "Η τροχαία πάντως προειδοποιεί ότι η οφθαλμαπάτη λειτουργεί μόνο από τη μία κατεύθυνση και μπορεί να ξαφνιάσει τους μοτοσικλετιστές, που ίσως φρενάρουν απότομα. Συνιστά στους οδηγούς να πλησιάζουν τα σχολεία με χαμηλή ταχύτητα, όπως άλλωστε ορίζει ο νόμος, είτε η διάβαση είναι «τρισδιάστατη» είτε όχι.", "The traffic police warn, however, that the illusion only works from one direction and may startle motorcyclists, who might brake sharply. They advise drivers to approach schools at low speed, as the law requires anyway, whether the crossing is 'three-dimensional' or not."),
 ],
 "questions": [
  Q("Πώς μοιάζουν οι νέες διαβάσεις από μακριά;", ["Σαν φωτεινές πινακίδες", "Σαν τρισδιάστατα εμπόδια πάνω από τον δρόμο", "Σαν λακκούβες στον δρόμο", "Σαν ζωγραφιές παιδιών"], 1, "να μοιάζουν με τρισδιάστατα εμπόδια που αιωρούνται πάνω από τον δρόμο"),
  Q("Τι παραδέχεται ο δήμος για τα αποτελέσματα στο εξωτερικό;", ["Ότι ήταν εντυπωσιακά", "Ότι οι διαβάσεις καταργήθηκαν", "Ότι δεν είναι πάντα σαφή", "Ότι προκάλεσαν ατυχήματα"], 2, "με αποτελέσματα που, όπως παραδέχεται ο δήμος, δεν είναι πάντα σαφή"),
  Q("Τι θα γίνει αν η ταχύτητα δεν μειωθεί αισθητά;", ["Οι διαβάσεις θα ξαναβαφτούν με τον συνηθισμένο τρόπο", "Θα μπουν φανάρια", "Θα αυξηθούν τα πρόστιμα", "Το πείραμα θα επεκταθεί σε όλη την πόλη"], 0, "οι διαβάσεις θα ξαναβαφτούν με τον συνηθισμένο τρόπο"),
  Q("Γιατί ανησυχεί η τροχαία για τους μοτοσικλετιστές;", ["Γιατί δεν βλέπουν καλά τις λωρίδες", "Γιατί οδηγούν πολύ γρήγορα κοντά στα σχολεία", "Γιατί η βαφή γλιστράει όταν βρέχει", "Γιατί μπορεί να ξαφνιαστούν και να φρενάρουν απότομα"], 3, "μπορεί να ξαφνιάσει τους μοτοσικλετιστές, που ίσως φρενάρουν απότομα"),
 ],
 "gloss": {"διαβάσεις πεζών": "διάβαση πεζών — pedestrian crossing", "ασυνήθιστο": "ασυνήθιστος — unusual", "λωρίδες": "λωρίδα — stripe; lane", "τρισδιάστατα": "τρισδιάστατος — three-dimensional", "εμπόδια": "εμπόδιο — obstacle", "αιωρούνται": "αιωρούμαι — to float, hover", "ενστικτωδώς": "ενστικτωδώς — instinctively", "οφθαλμαπάτη": "οφθαλμαπάτη — optical illusion", "πινακίδων": "πινακίδα — number plate; sign", "αισθητά": "αισθητά — noticeably", "τροχαία": "τροχαία — traffic police", "ξαφνιάσει": "ξαφνιάζω — to startle, surprise"}
})

ITEMS.append({
 "id": "l265-vm-paradosi-stromatos", "title": "Μήνυμα από το κατάστημα για την παράδοση του καινούριου στρώματος", "title_en": "A message from the shop about delivering your new mattress", "type": "voicemail", "level": "B2",
 "context_el": "Αγοράσατε ένα καινούριο στρώμα και έναν καινούριο σκελετό κρεβατιού. Ακούτε ένα μήνυμα από το κατάστημα για την παράδοση.",
 "script": [
  L("Υπάλληλος", "m", "Καλησπέρα σας, ο Νίκος είμαι από το κατάστημα με τα στρώματα. Η παράδοση θα γίνει την Τρίτη, ανάμεσα στις εννιά και στη μία. Μισή ώρα πριν φτάσουν, οι μεταφορείς θα σας στείλουν μήνυμα στο κινητό, οπότε δεν χρειάζεται να περιμένετε όλο το πρωί δίπλα στην πόρτα.", "Good evening, it's Nikos from the mattress shop. The delivery will be on Tuesday, between nine and one. Half an hour before they arrive, the delivery men will send you a text, so you don't need to wait by the door all morning."),
  L("Υπάλληλος", "m", "Όπως είχαμε συμφωνήσει, θα πάρουν μαζί τους το παλιό σας στρώμα για ανακύκλωση, χωρίς επιπλέον χρέωση. Για τον παλιό σκελετό όμως, η απομάκρυνση κοστίζει είκοσι ευρώ, γιατί πρέπει να λυθεί· αν τον έχετε ήδη λύσει εσείς, θα τον πάρουν δωρεάν.", "As we agreed, they will take your old mattress with them for recycling, at no extra charge. For the old bed frame, however, removal costs twenty euros, because it has to be taken apart; if you've already taken it apart yourself, they'll take it for free."),
  L("Υπάλληλος", "m", "Το στρώμα σας έχει δοκιμαστική περίοδο εκατό νυχτών: αν δεν σας ταιριάζει, μπορείτε να το αλλάξετε με άλλο. Υπάρχει όμως μια προϋπόθεση. Πρέπει να το χρησιμοποιείτε με προστατευτικό κάλυμμα, γιατί ένα στρώμα με λεκέδες δεν γίνεται δεκτό για αλλαγή.", "Your mattress has a trial period of a hundred nights: if it doesn't suit you, you can exchange it for another. There is, however, one condition. You must use it with a protective cover, because a mattress with stains is not accepted for exchange."),
  L("Υπάλληλος", "m", "Και κάτι ακόμα: τις πρώτες δύο-τρεις εβδομάδες είναι φυσιολογικό να σας φαίνεται πιο σκληρό απ’ ό,τι στο κατάστημα, μέχρι να συνηθίσει και το σώμα σας. Γυρίζετέ το ανάποδα, από το κεφάλι στα πόδια, κάθε τρεις μήνες περίπου. Αν έχετε απορίες, καλέστε μας. Καλά όνειρα!", "And one more thing: for the first two or three weeks it's normal for it to feel harder than in the shop, until your body gets used to it as well. Turn it round, head to foot, about every three months. If you have any questions, call us. Sweet dreams!"),
 ],
 "questions": [
  Q("Πώς θα ξέρετε πότε έρχονται οι μεταφορείς;", ["Θα σας τηλεφωνήσει το κατάστημα το πρωί", "Θα σας στείλουν μήνυμα μισή ώρα πριν", "Θα χτυπήσουν το κουδούνι στις εννιά", "Θα το δείτε σε μια εφαρμογή"], 1, "Μισή ώρα πριν φτάσουν, οι μεταφορείς θα σας στείλουν μήνυμα στο κινητό"),
  Q("Πότε η απομάκρυνση του παλιού σκελετού είναι δωρεάν;", ["Αν αγοράσετε και μαξιλάρια", "Αν η παράδοση γίνει το πρωί", "Αν τον έχετε ήδη λύσει εσείς", "Αν είναι ξύλινος"], 2, "αν τον έχετε ήδη λύσει εσείς, θα τον πάρουν δωρεάν"),
  Q("Ποια προϋπόθεση υπάρχει για να αλλάξετε το στρώμα;", ["Να το χρησιμοποιείτε με προστατευτικό κάλυμμα", "Να έχετε την απόδειξη σε χαρτί", "Να το επιστρέψετε μέσα σε μία εβδομάδα", "Να πληρώσετε τα μεταφορικά"], 0, "Πρέπει να το χρησιμοποιείτε με προστατευτικό κάλυμμα"),
  Q("Τι λέει ο υπάλληλος για τις πρώτες εβδομάδες;", ["Ότι το στρώμα πρέπει να αεριστεί", "Ότι δεν πρέπει να το γυρίσετε", "Ότι μπορεί να μυρίζει λίγο", "Ότι είναι φυσιολογικό να φαίνεται πιο σκληρό"], 3, "είναι φυσιολογικό να σας φαίνεται πιο σκληρό απ’ ό,τι στο κατάστημα"),
 ],
 "gloss": {"στρώμα": "στρώμα — mattress", "σκελετό κρεβατιού": "σκελετός κρεβατιού — bed frame", "παράδοση": "παράδοση — delivery", "μεταφορείς": "μεταφορέας — delivery man, carrier", "χρέωση": "χρέωση — charge", "απομάκρυνση": "απομάκρυνση — removal", "λυθεί": "λύνομαι — to be taken apart; to be untied", "δοκιμαστική περίοδο": "δοκιμαστική περίοδος — trial period", "προϋπόθεση": "προϋπόθεση — condition, prerequisite", "προστατευτικό κάλυμμα": "προστατευτικό κάλυμμα — protective cover", "λεκέδες": "λεκές — stain", "ανάποδα": "ανάποδα — the other way round, upside down"}
})

ITEMS.append({
 "id": "l265-c1-mono-fakelaki-tsagiou", "title": "Ένα δείγμα που οι πελάτες έβαλαν στο νερό: πώς γεννήθηκε το φακελάκι του τσαγιού", "title_en": "A sample customers dropped into the water: how the tea bag was born", "type": "monologue", "level": "C1",
 "context_el": "Ακούτε ένα απόσπασμα από μια ομιλία για τις τυχαίες εφευρέσεις, σε ένα φεστιβάλ επιστήμης.",
 "script": [
  L("Ομιλητής", "m", "Η πιο γνωστή εκδοχή της ιστορίας μάς πηγαίνει στη Νέα Υόρκη, γύρω στο 1908. Ένας έμπορος τσαγιού, ο Τόμας Σάλιβαν, για να γλιτώσει χρήματα, άρχισε να στέλνει στους πελάτες του δείγματα όχι σε μεταλλικά κουτάκια, αλλά σε μικρά μεταξωτά σακουλάκια.", "The best-known version of the story takes us to New York, around 1908. A tea merchant, Thomas Sullivan, to save money, began sending his customers samples not in small metal tins but in small silk bags."),
  L("Ομιλητής", "m", "Κάποιοι πελάτες, που μάλλον δεν κατάλαβαν ότι έπρεπε να ανοίξουν το σακουλάκι, το βύθισαν ολόκληρο στο ζεστό νερό, και ανακάλυψαν ότι έτσι δεν έμεναν φύλλα στο φλιτζάνι. Σύντομα ζητούσαν το τσάι τους σε σακουλάκια. Πρέπει όμως να πούμε ότι η ιστορία αυτή στηρίζεται κυρίως σε μεταγενέστερες αφηγήσεις.", "Some customers, who probably didn't realise they were supposed to open the bag, dipped it whole into the hot water, and discovered that this way no leaves were left in the cup. Soon they were asking for their tea in bags. We should say, though, that this story rests mainly on later accounts."),
  L("Ομιλητής", "m", "Και η ιδέα δεν ήταν εντελώς καινούρια: ήδη το 1901 δύο γυναίκες από το Μιλγουόκι είχαν καταθέσει αίτηση για δίπλωμα ευρεσιτεχνίας για μια υφασμάτινη θήκη για φύλλα τσαγιού, που θα έβγαζε μόνο ένα φλιτζάνι. Αργότερα, το μετάξι αντικαταστάθηκε από γάζα και στη συνέχεια από ειδικό χαρτί, που δεν διαλύεται στο νερό.", "And the idea wasn't entirely new: as early as 1901 two women from Milwaukee had applied for a patent for a cloth holder for tea leaves that would make just one cup. Later, silk was replaced by gauze and then by special paper that does not fall apart in water."),
  L("Ομιλητής", "m", "Το ενδιαφέρον είναι ότι στη Βρετανία, τη χώρα που πίνει τόσο πολύ τσάι, το φακελάκι αντιμετωπίστηκε για δεκαετίες με καχυποψία, ως αμερικανική ευκολία για ανθρώπους βιαστικούς. Σύμφωνα με συχνά αναφερόμενες εκτιμήσεις, στο τέλος της δεκαετίας του 1960 λιγότερο από το ένα δέκατο του τσαγιού που πουλιόταν εκεί ήταν σε φακελάκια· σήμερα είναι η συντριπτική πλειονότητα. Η συνήθεια, όπως βλέπετε, νικιέται, αλλά αργά.", "Interestingly, in Britain, the country that drinks so much tea, the bag was viewed with suspicion for decades, as an American convenience for people in a hurry. According to frequently cited estimates, at the end of the 1960s less than a tenth of the tea sold there was in bags; today it is the overwhelming majority. Habit, as you see, can be beaten, but slowly."),
 ],
 "questions": [
  Q("Γιατί, σύμφωνα με την ιστορία, ο Σάλιβαν έστελνε δείγματα σε σακουλάκια;", ["Για να μη χαλάει το τσάι", "Για να γλιτώσει χρήματα", "Για να φαίνονται πιο κομψά", "Γιατί του το ζήτησαν οι πελάτες"], 1, "για να γλιτώσει χρήματα"),
  Q("Τι λέει ο ομιλητής για την αξιοπιστία της ιστορίας;", ["Ότι επιβεβαιώνεται από τα βιβλία της εταιρείας", "Ότι την εφηύρε μια διαφήμιση", "Ότι στηρίζεται κυρίως σε μεταγενέστερες αφηγήσεις", "Ότι είναι απολύτως ψεύτικη"], 2, "η ιστορία αυτή στηρίζεται κυρίως σε μεταγενέστερες αφηγήσεις"),
  Q("Τι είχαν κάνει δύο γυναίκες από το Μιλγουόκι το 1901;", ["Είχαν ζητήσει δίπλωμα ευρεσιτεχνίας για μια υφασμάτινη θήκη για τσάι", "Είχαν ανοίξει το πρώτο τεϊοποτείο της πόλης", "Είχαν εφεύρει το χάρτινο φίλτρο του καφέ", "Είχαν φέρει το τσάι από την Ινδία"], 0, "είχαν καταθέσει αίτηση για δίπλωμα ευρεσιτεχνίας για μια υφασμάτινη θήκη για φύλλα τσαγιού"),
  Q("Πώς αντιμετωπίστηκε αρχικά το φακελάκι στη Βρετανία;", ["Με ενθουσιασμό από τους νέους", "Ως πολυτέλεια για πλούσιους", "Ως ιατρική καινοτομία", "Με καχυποψία, ως αμερικανική ευκολία για βιαστικούς"], 3, "αντιμετωπίστηκε για δεκαετίες με καχυποψία, ως αμερικανική ευκολία για ανθρώπους βιαστικούς"),
 ],
 "gloss": {"εκδοχή": "εκδοχή — version (of a story)", "έμπορος": "έμπορος — merchant, trader", "γλιτώσει": "γλιτώνω — to save; to escape", "δείγματα": "δείγμα — sample", "μεταξωτά": "μεταξωτός — silk (adj.)", "βύθισαν": "βυθίζω — to dip, sink", "μεταγενέστερες": "μεταγενέστερος — later, subsequent", "δίπλωμα ευρεσιτεχνίας": "δίπλωμα ευρεσιτεχνίας — patent", "γάζα": "γάζα — gauze", "διαλύεται": "διαλύομαι — to fall apart, dissolve", "καχυποψία": "καχυποψία — suspicion, distrust", "συντριπτική": "συντριπτικός — overwhelming"}
})

ITEMS.append({
 "id": "l265-c1-int-ichitiko-archeio", "title": "Φωνές που κινδυνεύουν να σβήσουν: μια αρχειονόμος σώζει παλιές ηχογραφήσεις", "title_en": "Voices in danger of fading: an archivist saves old sound recordings", "type": "interview", "level": "C1",
 "context_el": "Ακούτε μια συνέντευξη σε μια ραδιοφωνική εκπομπή για τον πολιτισμό με την υπεύθυνη ενός ηχητικού αρχείου, μια αρχειονόμο.",
 "script": [
  L("Δημοσιογράφος", "m", "Πολλοί πιστεύουν ότι μια μαγνητοταινία ή ένας παλιός δίσκος, αν μείνουν σε ένα συρτάρι, θα ακούγονται για πάντα. Ισχύει;", "Many people believe that a magnetic tape or an old record, if left in a drawer, will be playable forever. Is that true?"),
  L("Αρχειονόμος", "f", "Δυστυχώς όχι. Κάθε υλικό γερνάει με τον δικό του τρόπο. Σε ορισμένες μαγνητοταινίες από τις δεκαετίες του ’70 και του ’80, η κόλλα που συγκρατεί το μαγνητικό στρώμα απορροφά υγρασία και γίνεται κολλώδης· αν τις βάλετε απευθείας σε ένα μαγνητόφωνο, μπορεί να καταστραφούν με το πρώτο πέρασμα.", "Unfortunately not. Every material ages in its own way. In some magnetic tapes from the '70s and '80s, the binder that holds the magnetic layer absorbs moisture and becomes sticky; if you put them straight into a tape recorder, they can be destroyed on the first pass."),
  L("Δημοσιογράφος", "m", "Και τι κάνετε σε αυτή την περίπτωση;", "And what do you do in that case?"),
  L("Αρχειονόμος", "f", "Κάτι που ακούγεται σαν μαγειρική: τις «ψήνουμε» για αρκετές ώρες σε χαμηλή θερμοκρασία, σε ειδικό φούρνο, ώστε να φύγει προσωρινά η υγρασία. Έχουμε τότε ένα μικρό παράθυρο, λίγες μέρες ή εβδομάδες, για να τις ψηφιοποιήσουμε μία και καλή. Δεύτερη ευκαιρία συχνά δεν υπάρχει.", "Something that sounds like cooking: we 'bake' them for several hours at a low temperature, in a special oven, so that the moisture leaves temporarily. We then have a small window, a few days or weeks, to digitise them once and for all. There often isn't a second chance."),
  L("Δημοσιογράφος", "m", "Τι είδους ηχογραφήσεις φτάνουν σε εσάς;", "What kind of recordings reach you?"),
  L("Αρχειονόμος", "f", "Από ραδιοφωνικές εκπομπές μέχρι κασέτες που έστελναν οι μετανάστες στις οικογένειές τους αντί για γράμματα. Αυτές οι οικογενειακές κασέτες με συγκινούν περισσότερο: ακούς πώς μιλούσαν οι άνθρωποι στο σπίτι, με τις λέξεις του χωριού τους, κάτι που δεν θα βρεις σε κανένα επίσημο αρχείο. Γι’ αυτό λέω σε όλους: μην πετάτε τις παλιές κασέτες χωρίς να ρωτήσετε πρώτα ένα αρχείο.", "From radio programmes to cassettes that emigrants sent to their families instead of letters. Those family cassettes move me most: you hear how people spoke at home, with the words of their village, something you won't find in any official archive. That's why I tell everyone: don't throw away old cassettes without asking an archive first."),
 ],
 "questions": [
  Q("Τι συμβαίνει σε ορισμένες μαγνητοταινίες των δεκαετιών του ’70 και του ’80;", ["Χάνουν το χρώμα τους", "Η κόλλα τους απορροφά υγρασία και γίνεται κολλώδης", "Σπάνε όταν κάνει κρύο", "Ο ήχος τους γίνεται πιο δυνατός"], 1, "η κόλλα που συγκρατεί το μαγνητικό στρώμα απορροφά υγρασία και γίνεται κολλώδης"),
  Q("Γιατί «ψήνουν» τις ταινίες σε ειδικό φούρνο;", ["Για να τις αποστειρώσουν", "Για να διορθώσουν τον ήχο", "Για να φύγει προσωρινά η υγρασία", "Για να τις κάνουν πιο μαλακές"], 2, "ώστε να φύγει προσωρινά η υγρασία"),
  Q("Τι σημαίνει ότι «δεύτερη ευκαιρία συχνά δεν υπάρχει»;", ["Ότι η ψηφιοποίηση πρέπει να γίνει μέσα σε λίγο χρόνο και μία φορά", "Ότι οι ταινίες δεν μπορούν να ψηθούν ξανά ποτέ", "Ότι το αρχείο δεν έχει αρκετά χρήματα", "Ότι οι ιδιοκτήτες δεν τις δίνουν δεύτερη φορά"], 0, "Έχουμε τότε ένα μικρό παράθυρο ... για να τις ψηφιοποιήσουμε μία και καλή"),
  Q("Γιατί συγκινούν την αρχειονόμο οι οικογενειακές κασέτες;", ["Γιατί είναι οι πιο παλιές του αρχείου", "Γιατί έχουν καλύτερη ποιότητα ήχου", "Γιατί περιέχουν σπάνια τραγούδια", "Γιατί δείχνουν πώς μιλούσαν οι άνθρωποι στο σπίτι"], 3, "ακούς πώς μιλούσαν οι άνθρωποι στο σπίτι, με τις λέξεις του χωριού τους"),
 ],
 "gloss": {"μαγνητοταινία": "μαγνητοταινία — magnetic tape", "συρτάρι": "συρτάρι — drawer", "γερνάει": "γερνάω — to age, grow old", "συγκρατεί": "συγκρατώ — to hold together", "στρώμα": "στρώμα — layer", "κολλώδης": "κολλώδης — sticky", "μαγνητόφωνο": "μαγνητόφωνο — tape recorder", "ψηφιοποιήσουμε": "ψηφιοποιώ — to digitise", "μία και καλή": "μία και καλή — once and for all", "κασέτες": "κασέτα — cassette", "μετανάστες": "μετανάστης — emigrant, migrant", "αρχειονόμο": "αρχειονόμος — archivist"}
})

rnd = random.Random(265)  # spread the right answers over the four positions (the page shows options in file order)
for it in ITEMS:
    for q in it["questions"]: rnd.shuffle(q["options"])
for it in ITEMS:
    for q in it["questions"]: assert q["answer"] in q["options"], (it["id"], q["q"])
    for k in it["gloss"]:
        if not (any(k in s["el"] for s in it["script"]) or k in it["context_el"]): raise SystemExit(f"gloss key not in text: {it['id']} {k}")
